import {createTransformationRenderer,loadTransformation,transformationEndFrame} from '../../src/evolution/transformation'
import {loadAwakenedArt} from '../../src/evolution/atlas'
import type {Scene} from '../../src/shared/types'
const choices=[['fox','classic','小狐 · 舒尾凝纹'],['piranha','classic','食人花 · 蓓蕾绽放'],['luckycat','classic','招财猫 · 合爪招福'],['buddy','classic','牛马 · 蹄起曙光'],['feidudu','classic','肥嘟嘟 · 整装敬礼'],['beaver','sunny','海狸 · 戴帽出发'],['hamster','classic','仓鼠 · 鼓腮蓄力'],['cultivation','azure','修仙 · 结印升袍'],['battery','classic','电池 · 能量合壳'],['aquarium','sailor','小鱼 · 展鳍领航'],['skadi','sakura','月汐 · 樱华展裙'],['potato','gundam','土豆 · 星核合甲']]as const
const canvas=document.querySelector<HTMLCanvasElement>('#canvas')!,ctx=canvas.getContext('2d')!,button=document.querySelector<HTMLButtonElement>('#play')!
const actors=await Promise.all(choices.map(async([scene,skin,name])=>{const [poses,art]=await Promise.all([loadTransformation(scene as Scene,skin),loadAwakenedArt(scene as Scene,skin)]);const c=document.createElement('canvas');c.width=c.height=512;return{name,canvas:c,draw:createTransformationRenderer(scene as Scene,skin,poses),target:art.frames[transformationEndFrame(scene,40,art.frames.length)]!}}))
let raf=0
function paint(ms:number){ctx.fillStyle='#eaf0e9';ctx.fillRect(0,0,1280,1080);actors.forEach((actor,i)=>{const x=i%4*320,y=Math.floor(i/4)*360;actor.draw(actor.canvas.getContext('2d')!,ms,1600,actor.target);ctx.fillStyle='#dce6dc';ctx.beginPath();ctx.roundRect(x+10,y+8,300,334,20);ctx.fill();ctx.drawImage(actor.canvas,x+10,y+8,300,300);ctx.fillStyle='#345443';ctx.font='18px system-ui';ctx.textAlign='center';ctx.fillText(actor.name,x+160,y+328)})}
button.disabled=false;button.textContent='一起变身';button.onclick=()=>{cancelAnimationFrame(raf);const start=performance.now();function tick(now:number){paint(Math.min(1600,now-start));if(now-start<1600)raf=requestAnimationFrame(tick)}raf=requestAnimationFrame(tick)};paint(0);canvas.dataset.ready='true'
